cases=[]
def add(name,raw=None,kind='file',extra=None):
 p=work/(name+'.json')
 if raw is not None:p.write_bytes(raw)
 if kind=='directory':p.mkdir()
 row=dict(name=name,path=str(p),kind=kind)
 if raw is not None:row.update(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest(),hex=raw.hex() if len(raw)<4096 else None)
 if extra:row.update(extra)
 cases.append(row)
bare=json.loads((out.parent/'evidence-source-file-reference-r1/file-goldens.json').read_text())['cases']
record=next(c['input'] for c in bare if c['name']=='bare')
bundle=next(c['input'] for c in bare if c['name']=='one')
add('bare-record',json.dumps(record,ensure_ascii=False,separators=(',',':')).encode())
add('canonical-bundle',json.dumps(bundle,ensure_ascii=False,separators=(',',':')).encode())
add('empty',b'')
add('whitespace',b' \n\t\r')
add('invalid-object',b'{not-json}')
add('bom',bytes.fromhex('efbbbf')+b'{}')
add('invalid-utf8',b'{"bad":"'+bytes([255])+b'"}')
add('truncated-utf8',b'"'+bytes.fromhex('e282'))
add('directory',kind='directory')
